  const companyCode = scope(req).companyCode;
  const q = String(req.query.q || "").trim();
  if (q.length < 2 || q.length > 80) return [];
  const escaped = q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return CustomerModel.find({ companyCode, status: "active", $or: [{ name: new RegExp(escaped, "i") }, { phone: new RegExp(escaped) }, { customerCode: new RegExp(escaped, "i") }] })
    .select("_id customerCode name phone pointsBalance").limit(10).lean();
})

operate, handle(async (req) => {
  if (!Types.ObjectId.isValid(req.params.id)) throw Object.assign(new Error("Khách hàng không hợp lệ."), { status: 400 });
  const companyCode = scope(req).companyCode;
  const manager = await hasEffectiveRetailCapability(req.user || {}, "manager");
  if (!manager && !await getCustomerBrief({ companyCode }, req.params.id)) {
    throw Object.assign(new Error("Không tìm thấy khách hàng."), { status: 404 });
  }
  const customer = await CustomerModel.findOne({ _id: req.params.id, companyCode }).select("pointsBalance totalPointsEarned totalPointsRedeemed").lean();
  if (!customer) throw Object.assign(new Error("Không tìm thấy khách hàng."), { status: 404 });
  return { balance: Number(customer.pointsBalance || 0), totalEarned: Number(customer.totalPointsEarned || 0), totalRedeemed: Number(customer.totalPointsRedeemed || 0),
    ledger: manager ? await RetailPointLedgerModel.find({ companyCode, customerId: req.params.id }).sort({ createdAt: -1 }).limit(100).lean() : [] };
})

partnerManage, handle(async (req) => {
  const branch = scope(req), partnerId = String(req.body?.partnerId || ""), kind = String(req.body?.kind || ""), sku = kind === "repair" ? "*" : String(req.body?.sku || "*").trim().toUpperCase(), ratePercent = Number(req.body?.ratePercent);
  if (!Types.ObjectId.isValid(partnerId) || !await RetailPartnerModel.exists({ companyCode: branch.companyCode, _id: partnerId, roles: "collaborator" })) throw bad("Cộng tác viên bán lẻ không hợp lệ.");
  if (!["sale", "repair"].includes(kind) || !sku || !Number.isFinite(ratePercent) || ratePercent < 0 || ratePercent > 100) throw bad("Chính sách hoa hồng không hợp lệ.");
  const effectiveFrom = new Date(`${String(req.body.effectiveFrom || "")}T00:00:00.000Z`);
  if (Number.isNaN(effectiveFrom.valueOf())) throw bad("Ngày hiệu lực không hợp lệ.");
  const filter = { companyCode: branch.companyCode, partnerId, kind: kind as "sale" | "repair", sku };
  return RetailCommissionPolicyModel.findOneAndUpdate(filter, { $set: { ratePercent, effectiveFrom, active: req.body.active !== false, updatedBy: String(req.user.id), updatedAt: new Date() }, $inc: { version: 1 }, $setOnInsert: filter }, { upsert: true, returnDocument: "after" }).lean();
})

partnerManage, handle(async (req) => {
  const company = retailScopeFromRequest(req.user || {}, { companyCode: req.query.companyCode }).companyCode;
  const accounts = await RetailCommissionAccountModel.find({ companyCode: company }).select("partnerId balance").lean();
  return accounts.map((account) => ({ partnerId: account.partnerId, balance: Number(account.balance || 0) }));
})

manager, run(async r => {
    const data = validateManagement("settings", r.body);
    const financeScope = await scope(r);
    return FinanceManagementSettingsModel.findOneAndUpdate({ ...financeScope, period: data.period }, { $set: { ...data, updatedBy: r.user.id } }, { upsert: true, returnDocument: "after", runValidators: true });
})

requirePermission(WORKER_READ_PERMISSION) as any, async (req: any, res) => {
